.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.cd-hd{position:absolute;left:90px;right:90px;top:280px;font-size:88px;font-weight:var(--rf-heading-weight);letter-spacing:-.04em;line-height:1}
.ed{position:absolute;left:60px;right:60px;top:460px;border-radius:32px;background:color-mix(in srgb,var(--rf-bg) 70%,#000);box-shadow:0 0 0 2px color-mix(in srgb,var(--rf-text) 10%,transparent);overflow:hidden;animation:k-rise .9s cubic-bezier(.16,1,.3,1) 0s both}
.ed-bar{height:70px;display:flex;align-items:center;gap:12px;padding:0 28px;background:color-mix(in srgb,var(--rf-text) 6%,transparent)}
.ed-bar i{width:20px;height:20px;border-radius:50%;background:#ff5f57}.ed-bar i:nth-child(2){background:#febc2e}.ed-bar i:nth-child(3){background:#28c840}
.ed-bar span{margin-left:20px;font:500 26px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}
.ed-code{padding:34px 34px 40px;font:500 33px/1.65 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-text)}
.ln{display:flex;white-space:pre}
.no{width:56px;flex:none;color:color-mix(in srgb,var(--rf-text) 30%,transparent)}
.ty{display:inline-block;overflow:hidden;width:calc(var(--ch) * 1ch + 2px);animation-name:ty;animation-fill-mode:both}
@keyframes ty{from{width:0}}
.k{font-style:normal;color:var(--rf-accent)}.c{font-style:normal;color:color-mix(in srgb,var(--rf-text) 42%,transparent)}.st{font-style:normal;color:color-mix(in srgb,var(--rf-accent) 55%,var(--rf-text))}
.term{display:flex;align-items:center;gap:16px;margin:0 34px 34px;padding:26px 30px;border-radius:20px;background:color-mix(in srgb,var(--rf-text) 6%,transparent);font:600 30px/1.3 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-text)}
.pr{color:var(--rf-muted)}.ok{margin-left:auto;color:var(--rf-accent);display:flex}

